use pretty_assertions::assert_eq;
use serde_json::json;

use super::McpServerConfig;

fn server() -> serde_json::Value {
    json!({"url": "http://localhost:8181/mcp"})
}

#[test]
fn owner_oauth_config_defaults_to_no_extra_origins() {
    let config: McpServerConfig = serde_json::from_value(server()).unwrap();
    assert!(config.oauth_authorization_origins().is_empty());
    let mut value = server();
    value["oauth"] = json!({"client_id": "owner-client"});
    let config: McpServerConfig = serde_json::from_value(value).unwrap();
    assert!(config.oauth_authorization_origins().is_empty());
    assert!(
        serde_json::to_value(config).unwrap()["oauth"]
            .get("authorization_origins")
            .is_none()
    );
}

#[test]
fn explicit_owner_oauth_config_round_trips_exact_grants() {
    let mut value = server();
    value["oauth"] = json!({
        "client_id": "owner-client",
        "callback_port": 43111,
        "authorization_origins": ["http://localhost:8383", "https://authorization.example"]
    });
    let config: McpServerConfig = serde_json::from_value(value).unwrap();
    assert_eq!(
        config.oauth_authorization_origins().as_slice(),
        &[
            "http://localhost:8383".to_string(),
            "https://authorization.example".to_string()
        ]
    );
    assert_eq!(config.oauth_client_id(), Some("owner-client"));
    assert_eq!(
        config.oauth_callback_port(/*global_callback_port*/ None),
        Some(43111)
    );
    let encoded = serde_json::to_value(&config).unwrap();
    let recovered: McpServerConfig = serde_json::from_value(encoded).unwrap();
    assert_eq!(recovered, config);
}

#[test]
fn owner_oauth_config_rejects_duplicate_noncanonical_and_wrong_type_grants() {
    for invalid in [
        json!(null),
        json!({"origin": "http://localhost:8383"}),
        json!(["http://localhost:8383", "http://localhost:8383"]),
        json!(["http://localhost:8383/path"]),
        json!(["http://localhost:8383/"]),
        json!(["http://user:password@localhost:8383"]),
        json!(["http://169.254.169.254"]),
    ] {
        let mut value = server();
        value["oauth"] = json!({"authorization_origins": invalid});
        assert!(serde_json::from_value::<McpServerConfig>(value).is_err());
    }
}

codex-rs/config/src/mcp_types.rs.content:
//! MCP server configuration types.

use std::borrow::Cow;
use std::collections::HashMap;
use std::fmt;
use std::time::Duration;

use base64::Engine;
use base64::engine::general_purpose::URL_SAFE_NO_PAD;
use codex_protocol::config_types::ToolExposureSurface;
use codex_utils_path_uri::LegacyAppPathString;
use schemars::JsonSchema;
use serde::Deserialize;
use serde::Deserializer;
use serde::Serialize;
use serde::de::Error as SerdeError;

use crate::RequirementSource;

/// Effective MCP environment id when config omits `environment_id`.
pub const DEFAULT_MCP_SERVER_ENVIRONMENT_ID: &str = "local";

#[derive(Serialize, Deserialize, Debug, Clone, Copy, PartialEq, Eq, Default, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum AppToolApproval {
    #[default]
    Auto,
    Prompt,
    Writes,
    Approve,
}

impl AppToolApproval {
    /// Requires approval whenever either policy could require it.
    ///
    /// `Auto` and `Writes` are incomparable: each can require approval for a
    /// tool the other would approve. Their conservative intersection is `Prompt`.
    pub fn restrict_to(self, requested: Self) -> Self {
        match (self, requested) {
            (Self::Prompt, _) | (_, Self::Prompt) => Self::Prompt,
            (Self::Approve, mode) | (mode, Self::Approve) => mode,
            (Self::Auto, Self::Auto) => Self::Auto,
            (Self::Writes, Self::Writes) => Self::Writes,
            (Self::Auto, Self::Writes) | (Self::Writes, Self::Auto) => Self::Prompt,
        }
    }
}

/// Human-readable reason a configured MCP server was disabled after requirements
/// were applied.
///
/// `Display` is intentionally implemented for CLI/TUI status output; avoid
/// relying on `Debug` because enum variant syntax is not part of the user-facing
/// message contract.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum McpServerDisabledReason {
    /// The server is disabled, but there is no more specific user-facing reason.
    Unknown,
    /// The server was disabled by config requirements from the given source.
    Requirements { source: RequirementSource },
}

impl fmt::Display for McpServerDisabledReason {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            McpServerDisabledReason::Unknown => write!(f, "unknown"),
            McpServerDisabledReason::Requirements { source } => {
                write!(f, "requirements ({source})")
            }
        }
    }
}

/// Per-tool approval settings for a single MCP server tool.
#[derive(Serialize, Deserialize, Debug, Clone, PartialEq, Eq, Default, JsonSchema)]
#[schemars(deny_unknown_fields)]
pub struct McpServerToolConfig {
    /// Approval mode for this tool.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub approval_mode: Option<AppToolApproval>,
}

#[derive(Serialize, Deserialize, Debug, Clone, PartialEq, Eq, JsonSchema)]
#[serde(untagged, deny_unknown_fields)]
pub enum McpServerEnvVar {
    Name(String),
    Config {
        name: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        source: Option<String>,
    },
}

impl McpServerEnvVar {
    pub fn name(&self) -> &str {
        match self {
            McpServerEnvVar::Name(name) => name,
            McpServerEnvVar::Config { name, .. } => name,
        }
    }

    pub fn source(&self) -> Option<&str> {
        match self {
            McpServerEnvVar::Name(_) => None,
            McpServerEnvVar::Config { source, .. } => source.as_deref(),
        }
    }

    pub fn is_remote_source(&self) -> bool {
        self.source() == Some("remote")
    }

    pub fn validate_source(&self) -> Result<(), String> {
        match self.source() {
