                        root.plugin_identity.remote_plugin_id,
                    )
                })
                .collect::<Vec<_>>(),
            vec![(
                "sample@openai-curated-remote".to_string(),
                expected_remote_plugin_id.map(str::to_string),
            )],
        );
    }
}

